<script setup lang="ts">
import { ref, computed, nextTick, onMounted, onBeforeUnmount, watch } from 'vue'
import Viewport from './Viewport.vue'
import { state, selected, selection, selectObject, canGroup, groupSelected, ungroupSelected, collisionSelection, history, checkpoint, add, duplicate, remove, edit, undo, redo, save, load, createRoom, editRoom, toggleBaseboard, toggleCollisions, editStructuralColor, editFloorColor, editProjectName, FLOOR_COLOR, WALL_COLOR, isStructural, isOpening, type ObjectKind } from './editor'
const viewport=ref<InstanceType<typeof Viewport>>();const file=ref<HTMLInputElement>();const currentView=ref('Perspectiva')
const editingProjectName=ref(false),projectNameDraft=ref(''),projectNameInput=ref<HTMLInputElement>()
async function startProjectNameEdit(){projectNameDraft.value=state.projectName;editingProjectName.value=true;await nextTick();projectNameInput.value?.focus();projectNameInput.value?.select()}
function saveProjectName(){if(!projectNameDraft.value.trim())return;editProjectName(projectNameDraft.value);editingProjectName.value=false}
// Temporarily hidden toolbar switches; restore them in a future UI step.
const showToolbarCheckboxes=false
const roomEditorOpen=ref(false)
function toggleRoomEditor(){roomEditorOpen.value=!roomEditorOpen.value;paletteOpen.value=false}
watch(()=>state.room,room=>{if(!room)roomEditorOpen.value=false})
const paletteOpen=ref(false),colorControl=ref<HTMLElement>()
const paletteColors=[{name:'Blanco',value:'#f2f1ed'},{name:'Arena',value:'#d1c8ba'},{name:'Beige',value:'#e4d5c8'},{name:'Terracota',value:'#ad5b20'},{name:'Teja',value:'#915845'},{name:'Azul claro',value:'#bbcbd0'},{name:'Azul grisáceo',value:'#68858f'},{name:'Oliva',value:'#929879'},{name:'Gris',value:'#85867e'},{name:'Topo',value:'#9e897c'},{name:'Malva',value:'#77596e'}]
const surfaceColorTarget=ref<'walls'|'floor'>('walls')
const floorPalette=computed(()=>structurePalette.value&&surfaceColorTarget.value==='floor')
const structurePalette=computed(()=>!selected.value||isStructural(selected.value))
const paletteEnabled=computed(()=>structurePalette.value||selected.value?.type!=='group')
const paletteColor=computed(()=>floorPalette.value?(state.room?.floorColor??FLOOR_COLOR):structurePalette.value?state.structuralColor:selected.value?.color)
function applyPaletteColor(color:string){if(floorPalette.value)editFloorColor(color);else if(structurePalette.value)editStructuralColor(color);else edit('color',color)}
function resetPaletteColor(){applyPaletteColor(floorPalette.value?FLOOR_COLOR:structurePalette.value?WALL_COLOR:selected.value?.type==='door'?'#b78b61':selected.value?.type==='window'?'#7faec6':'#779b8e')}
function dismissPalette(e:PointerEvent){if(!colorControl.value?.contains(e.target as Node))paletteOpen.value=false}
watch(()=>state.selected,()=>paletteOpen.value=false)
const roomFields:{key:'width'|'depth'|'height';label:string}[]=[{key:'width',label:'Anchura'},{key:'depth',label:'Profundidad'},{key:'height',label:'Altura'}]
const additions:{type:ObjectKind;label:string;icon:string}[]=[{type:'door',label:'Puerta',icon:'▯'},{type:'window',label:'Ventana',icon:'⊞'},{type:'column',label:'Columna',icon:'▥'},{type:'beam',label:'Viga',icon:'━'}]
const visibleObjects=computed(()=>state.objects.filter(object=>roomEditorOpen.value===additions.some(item=>item.type===object.type)))
const editableObjectIds=computed(()=>visibleObjects.value.map(object=>object.id))
watch([editableObjectIds,selection],()=>{if(selection.value.some(object=>!editableObjectIds.value.includes(object.id)))selectObject('')})
const icons:Record<ObjectKind,string>={box:'◇',door:'▯',window:'⊞',column:'▥',beam:'━',group:'▣'}
function changeCollisions(e:Event){toggleCollisions();(e.target as HTMLInputElement).checked=collisionSelection.value.checked;(e.target as HTMLInputElement).indeterminate=collisionSelection.value.mixed}
function resetInput(e:Event,value:unknown){(e.target as HTMLInputElement).value=String(value??'')}
function resetRoomInput(e:Event,key:'width'|'depth'|'height'|'thickness'){resetInput(e,state.room?.[key])}
function input(e:Event){return (e.target as HTMLInputElement).value}
function changeView(){viewport.value?.view(currentView.value)}
function key(e:KeyboardEvent){if(e.key==='Escape'&&paletteOpen.value){paletteOpen.value=false;e.preventDefault();return}if(e.key==='Escape'&&roomEditorOpen.value){roomEditorOpen.value=false;e.preventDefault();return}if((e.target as HTMLElement).matches('input,select,textarea'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'){e.preventDefault();duplicate()}if(!e.ctrlKey&&!e.metaKey&&!e.altKey){if(e.key.toLowerCase()==='r'&&selected.value&&!isOpening(selected.value))state.transformMode='rotate';if(e.key.toLowerCase()==='w')state.transformMode='translate'}if(e.key==='Delete')remove();if(e.key==='Escape')selectObject('')}
watch(selected,object=>{if(!object||isOpening(object))state.transformMode='translate'})
onMounted(()=>{window.addEventListener('keydown',key);window.addEventListener('pointerdown',dismissPalette)});onBeforeUnmount(()=>{window.removeEventListener('keydown',key);window.removeEventListener('pointerdown',dismissPalette)})
</script>
<template>
<div class="app"><header><a class="brand" href="/">▦ <span>gridly<span class="dot">.</span></span></a><div class="project-name"><form v-if="editingProjectName" class="project-name-editor" @submit.prevent="saveProjectName"><input ref="projectNameInput" v-model="projectNameDraft" aria-label="Nombre del proyecto" maxlength="120" required @keydown.esc.stop="editingProjectName=false"><button type="submit" class="project-name-save" aria-label="Guardar nombre del proyecto" title="Guardar nombre del proyecto" :disabled="!projectNameDraft.trim()"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M5 3h12l4 4v14H3V3h2Z"/><path d="M7 3v6h9V3M7 21v-8h10v8"/></svg></button></form><button v-else class="project-name-button" title="Editar nombre del proyecto" @click="startProjectNameEdit">{{state.projectName}}</button></div><div class="header-actions"><button @click="file?.click()">Abrir</button><button class="primary" @click="save">↓ Descargar proyecto</button><input ref="file" hidden type="file" accept=".json" @change="e=>{const f=(e.target as HTMLInputElement).files?.[0];if(f)load(f);(e.target as HTMLInputElement).value=''}"></div></header>
<div class="workspace"><aside class="objects-panel"><template v-if="!roomEditorOpen"><button v-if="!state.room" class="add-button" @click="createRoom">＋ Crear habitación</button><button v-else :class="['object-row','room-row',{active:state.selected==='room'}]" @click="selectObject('room')"><span class="object-icon">▱</span><span>Habitación<small>{{state.room.width / 1000}} × {{state.room.depth / 1000}} m</small></span></button></template><template v-if="roomEditorOpen"><div class="construction-title">CONSTRUCCIÓN</div><div class="construction-buttons"><button v-for="item in additions" :key="item.type" :disabled="(item.type==='door'||item.type==='window')&&!state.room" @click="add(item.type)"><span>{{item.icon}}</span> {{item.label}}</button><button class="baseboard-button" :disabled="!state.room" :aria-pressed="!!state.room?.baseboard" @click="toggleBaseboard"><span>▰</span> {{state.room?.baseboard?'Quitar rodapié':'Rodapié'}}</button></div></template><button v-if="!roomEditorOpen" class="add-button" @click="add('box')">＋ Añadir elemento</button><div class="object-list"><button v-for="o in visibleObjects" :key="o.id" :class="['object-row',{active:selection.some(item=>item.id===o.id)}]" @click="e=>selectObject(o.id,e.ctrlKey||e.metaKey||e.shiftKey)"><span class="object-icon">{{icons[o.type??'box']}}</span><span>{{o.name}}</span><span class="swatch" :style="{background:o.color}"></span></button><p v-if="!visibleObjects.length && !roomEditorOpen" class="muted">Tu habitación está lista para amueblar.</p></div></aside>
<main><div class="canvas-wrap"><Viewport ref="viewport" :editable-object-ids="editableObjectIds"/><div class="toolbar" role="toolbar" aria-label="Herramientas del plano"><div class="toolbar-group"><button aria-label="Deshacer" title="Deshacer (Ctrl+Z)" :disabled="!history.undo" @click="undo"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="square" stroke-linejoin="miter"><path d="M4 12a8 8 0 1 1 2.3 5.7"/><path d="m1 9 3 3 3-3"/></svg></button><button aria-label="Rehacer" title="Rehacer (Ctrl+Mayús+Z)" :disabled="!history.redo" @click="redo"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="square" stroke-linejoin="miter"><g transform="translate(24 0) scale(-1 1)"><path d="M4 12a8 8 0 1 1 2.3 5.7"/><path d="m1 9 3 3 3-3"/></g></svg></button></div><span class="separator" aria-hidden="true"></span><div class="toolbar-group"><button class="group-action" :disabled="!canGroup" @click="groupSelected" title="Agrupar selección">Agrupar</button><button class="group-action" :disabled="selected?.type!=='group'" @click="ungroupSelected">Desagrupar</button></div><span v-if="showToolbarCheckboxes" class="separator" aria-hidden="true"></span><div v-if="showToolbarCheckboxes" class="toolbar-group"><label class="snap" title="Activar o desactivar las colisiones de los elementos opcionales. Vigas y columnas colisionan con otros tipos, pero pueden solaparse entre sí. Un estado mixto indica ajustes individuales."><input :checked="collisionSelection.checked" :indeterminate="collisionSelection.mixed" :aria-checked="collisionSelection.mixed?'mixed':collisionSelection.checked" type="checkbox" @change="changeCollisions"> Colisiones</label><label class="snap" title="Ajustar movimientos y tamaños en pasos de 50 mm; giros en pasos de 15°"><input v-model="state.snap" type="checkbox"> Snap</label><label class="snap" title="Ajustar caras a paredes, suelo y altura de la habitación (60 mm)"><input v-model="state.wallSnap" :disabled="!state.snap" type="checkbox"> Paredes</label></div><span class="separator" aria-hidden="true"></span><div ref="colorControl" class="color-control"><button aria-label="Selector de colores" :title="floorPalette?'Color del suelo':structurePalette?'Color de paredes, vigas y columnas':'Color del elemento seleccionado'" :disabled="!paletteEnabled" :aria-expanded="paletteOpen" aria-controls="toolbar-color-palette" :class="{active:paletteOpen}" @click="paletteOpen=!paletteOpen"><svg viewBox="0 0 32 32" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linejoin="miter"><path d="m7 7 13-2 8 5-9 17M5 8l10-5 9 18-10 5Z"/><path d="m9 16 11-5"/><circle cx="16" cy="22" r="2"/></svg></button><div v-if="paletteOpen" id="toolbar-color-palette" class="color-palette" role="group" :aria-label="floorPalette?'Color del suelo':structurePalette?'Color de la estructura':'Color del elemento'"><div v-if="structurePalette" class="surface-color-target"><button :aria-pressed="surfaceColorTarget==='walls'" @click="surfaceColorTarget='walls'">Paredes</button><button :disabled="!state.room" :aria-pressed="surfaceColorTarget==='floor'" @click="surfaceColorTarget='floor'">Suelo</button></div><button class="color-swatch reset-color" aria-label="Restaurar color original" title="Restaurar color original" @click="resetPaletteColor"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 5 14 14" stroke="#ff3b30" stroke-width="1.5"/></svg></button><button v-for="color in paletteColors" :key="color.value" class="color-swatch" :style="{backgroundColor:color.value}" :aria-label="color.name" :title="color.name" :aria-pressed="paletteColor?.toLowerCase()===color.value" @click="applyPaletteColor(color.value)"></button></div></div><span class="separator" aria-hidden="true"></span><select v-model="currentView" aria-label="Vista de cámara" @change="changeView"><option>Perspectiva</option><option>Superior</option><option>Frontal</option><option>Lateral</option></select><span class="separator" aria-hidden="true"></span><button class="edit-room-button" :class="{active:roomEditorOpen}" :disabled="!state.room" :aria-expanded="roomEditorOpen" aria-controls="room-editor" @click="toggleRoomEditor">{{roomEditorOpen?'Confirmar edición':'Editar estancia'}}</button></div></div></main>
<aside v-if="roomEditorOpen && state.room" id="room-editor" class="properties room-editor" aria-label="Editar estancia"><label v-for="f in roomFields" :key="f.key" class="field">{{f.label}}<div class="number-field"><input type="number" min="1" max="100000" step="50" :value="state.room[f.key]" @focus="checkpoint" @input="e=>editRoom(f.key,input(e))" @blur="e=>resetRoomInput(e,f.key)"><span>mm</span></div></label></aside></div><div v-if="state.error || state.autosaveError" role="alert" class="error">{{state.error || state.autosaveError}}<button @click="state.error='';state.autosaveError=''">Cerrar</button></div></div>
</template>





